#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Keep source-SHA normalization bounded and its artifact guard mandatory."""
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
PLUGIN = "build-logic/src/main/kotlin/openbank.test-provenance.gradle.kts"
SERVICE = "build-logic/src/main/kotlin/openbank.quarkus-service.gradle.kts"
HELPER = "build-logic/src/main/kotlin/com/openbank/buildlogic/BuildFactsInputs.kt"
BROKER_LIST = "val pactBrokerSystemProperties: List<String> = listOf("


def checks(plugin, service, helper):
    """(message, holds) per invariant. SUBJECTS is the number of these actually evaluated."""
    yield ("normalize only the two explicitly fingerprinted build-facts resources",
           re.findall(r'ignore\("([^"]+)"\)', plugin) == ["docs/00-build.md", "openbank-service-build.properties"])
    yield ("Test inputs must retain every non-SHA build-facts byte",
           'buildFactsInputs(classpath.files, normalizeCommit = name == "test" && !brokerConfigured)' in plugin)
    # One shared list: the keys forwarded to the test JVM are the keys that disable reuse.
    yield ("broker-configured ordinary tests must retain full metadata (shared pactBrokerSystemProperties)",
           'systemProperties.keys.any { it in pactBrokerSystemProperties }' in plugin and BROKER_LIST in helper)
    yield ("services must forward exactly the shared Pact Broker key list",
           'pactBrokerSystemProperties.forEach { key ->' in service
           and not re.search(r'systemProperty\(\s*"pact(broker)?\.(?!rootDir|writer)', service))
    yield ("tests must stamp the commit that actually executed them (outside task outputs)",
           'doFirst {' in plugin and 'executedCommit=' in plugin and 'providers.environmentVariable("GITHUB_SHA")' in plugin
           and 'outputs.file' not in plugin)
    yield ("services must apply the tested normalization plugin", 'id("openbank.test-provenance")' in service)
    yield ("Quarkus artifact keys must retain the full source SHA and metadata",
           bool(re.search(r'tasks.withType<QuarkusBuildTask>\(\).configureEach\s*\{\s*inputs.property\("unfilteredBuildFacts", providers.provider\s*\{\s*buildFactsInputs\(classpath.files, normalizeCommit = false\)', service)))
    for path in ("docs/00-build.md", "openbank-service-build.properties"):
        yield (f"packaged {path} must equal freshly generated bytes",
               f'== generatedServiceDocs.get().asFile.resolve("{path}").readText()' in service)
    yield ("fingerprints must cover directories and dependency JARs without resolving Gradle state",
           'ZipFile(file).use' in helper and 'flatMapIndexed' in helper)


def evaluate(plugin, service, helper):
    results = list(checks(plugin, service, helper))
    return [message for message, holds in results if not holds], len(results)


def main():
    texts = [(ROOT / path).read_text() for path in (PLUGIN, SERVICE, HELPER)]
    if "--self-test" in sys.argv:
        mutations = [(0, 'ignore("docs/00-build.md")', 'ignore("docs/**")'),
                     (0, 'normalizeCommit = name == "test"', 'normalizeCommit = false'),
                     (1, 'id("openbank.test-provenance")', ''),
                     (0, 'it in pactBrokerSystemProperties', 'it in setOf("pactbroker.url")'),
                     (1, 'pactBrokerSystemProperties.forEach { key ->', 'listOf("pactbroker.url").forEach { key ->'),
                     (1, 'systemProperty("pact.rootDir"', 'systemProperty("pactbroker.extra", "x")\n    systemProperty("pact.rootDir"'),
                     (0, 'doFirst {', 'doLast {'),
                     (1, 'normalizeCommit = false', 'normalizeCommit = name == "test"'),
                     (1, '== generatedServiceDocs.get().asFile.resolve("docs/00-build.md").readText()', ''),
                     (2, 'ZipFile(file).use', 'skipJarMetadata')]
        for index, old, new in mutations:
            fixture = texts.copy()
            assert old in fixture[index], f"mutation anchor missing: {old}"
            fixture[index] = fixture[index].replace(old, new)
            assert evaluate(*fixture)[0], f"accepted unsafe mutation: {old}"
        # The subject count is derived from what ran, so it falls if a check stops being evaluated.
        _, full = evaluate(*texts)
        assert full == sum(1 for _ in checks(*texts)) and full >= 6, f"subject count not derived: {full}"
        truncated = lambda *t: (m for i, m in enumerate(checks(*t)) if i < 3)  # noqa: E731
        assert len(list(truncated(*texts))) < full, "a dropped check did not lower SUBJECTS"
        print(f"Provenance cache guard: {len(mutations)} unsafe mutations rejected")
    errors, subjects = evaluate(*texts)
    for error in errors:
        print(f"::error::{error}")
    print(f"SUBJECTS={subjects}")
    return int(bool(errors))


if __name__ == "__main__":
    raise SystemExit(main())
